1	import AppKit
2	
3	/// The agent's project-level tools (spec §7.9): open, new, save, close, read,
4	/// and the playhead. Everything here mirrors a File-menu command or the
5	/// transport, and every edit goes through `ProjectDocument` exactly as the UI's
6	/// does. A path another open document holds is never written by `new_project`
7	/// or `save_project` (spec §11 #40): `close_project` closes that one first.
8	extension AgentServer {
9	
10	    // MARK: - Opening
11	
12	    /// `open_project` — File ▸ Open… (`AppDelegate`'s nil-target
13	    /// `openDocument:`). Takes a `.framejob` package OR any movie, sound file
14	    /// or picture the app handles: opening one of those builds a fresh
15	    /// untitled project sized and rated to it with the file as the first clip
16	    /// (spec §1), which is exactly what `ProjectDocument.read(from:ofType:)`
17	    /// does for a double-click.
18	    ///
19	    /// **Runs on the server thread** (`AgentServer.offMainTools`, spec §11
20	    /// #231), in three steps, so a WebM's copy, a re-copy on open or an
21	    /// ffmpeg conversion never holds the main thread: the already-open
22	    /// answer and the file's type on main; the read here, as AppKit's own
23	    /// concurrent read does it; then, on main, the document added and shown.
24	    /// It answers when the read ends, with no window and no question (MC-5).
25	    ///
26	    /// **One document per path** (spec §11 #234): each main-thread step is
27	    /// one block that sees a holder, or a person's open of the path still in
28	    /// flight (`ProjectDocumentController.isOpening`), or neither — and the
29	    /// last step adds in that same block. An open in flight is waited for
30	    /// (`afterPersonOpen`), and past `personOpenWait` the call is refused.
31	    func openProject(_ a: [String: Any]) throws -> String {
32	        let path = try requiredString(a, "path")
33	        let url = URL(fileURLWithPath: (path as NSString).expandingTildeInPath)
34	        guard FileManager.default.fileExists(atPath: url.path) else {
35	            throw ToolError(message: "No file at \(url.path)")
36	        }
37	        let controller = NSDocumentController.shared
38	        // An imported movie leaves its document UNTITLED (spec §1), so
39	        // NSDocumentController's own `document(for:)` cannot find it — the
40	        // path a project is known by is `AgentServer.path(of:)`. Compared
41	        // canonically, as in `target(_:)`: two spellings of one file that
42	        // failed to match here would open the SAME file twice.
43	        let found: (answer: String?, type: String)? = try afterPersonOpen {
44	            if let answer = try self.alreadyOpen(url) { return (answer, "") }
45	            if ProjectDocumentController.isOpening(url) { return nil }
46	            return (nil, try controller.typeForContents(of: url))
47	        }
48	        guard let known = found else { throw Self.beingOpened(url) }
49	        if let answer = known.answer { return answer }
50	        // A tool call never asks the conversion question (spec §11 MC-5):
51	        // the read runs on this thread, inside the import's no-asking scope.
52	        let made = try MediaImporter.withoutAsking {
53	            try controller.makeDocument(withContentsOf: url, ofType: known.type)
54	        }
55	        guard let document = made as? ProjectDocument else {
56	            throw ToolError(
57	                message: "\(url.lastPathComponent) did not open as a Frame Job project.")
58	        }
59	        let landed: String? = try afterPersonOpen {
60	            // A document that came to hold the path during the read wins:
61	            // the one made here was never added and has no window.
62	            if let answer = try self.alreadyOpen(url) {
63	                document.close()
64	                return answer
65	            }
66	            if ProjectDocumentController.isOpening(url) { return nil }
67	            controller.addDocument(document)
68	            document.makeWindowControllers()
69	            document.showWindows()
70	            controller.noteNewRecentDocumentURL(url)
71	            return try self.jsonResult(["project": self.summary(document)])
72	        }
73	        guard let answer = landed else {
74	            // The person's open outlasted the wait: theirs is the document,
75	            // and the one made here was never added or shown.
76	            onMain { document.close() }
77	            throw Self.beingOpened(url)
78	        }
79	        return answer
80	    }
81	
82	    /// The longest `open_project` waits, at each of its two steps, for a
83	    /// person's open of the same path to end (spec §11 #234). The app never
84	    /// reassigns it; a probe shortens it (`ProjectDocument.copyWatch`'s
85	    /// precedent).
86	    static var personOpenWait: TimeInterval = 30
87	
88	    /// One of `openProject`'s main-thread steps: `step` on main, where nil
89	    /// means a person's open of the path is in flight (spec §11 #234), again
90	    /// every 50 ms while it answers nil, until `personOpenWait` after its
91	    /// first nil; then nil. The sleep is this thread's and never main's: on
92	    /// main the deadline is at once. A hop to main is `onMain`'s and is not
93	    /// counted.
94	    private func afterPersonOpen<T>(_ step: () throws -> T?) throws -> T? {
95	        var deadline: Date?
96	        while true {
97	            if let found = try onMain(step) { return found }
98	            let now = Date()
99	            let limit = deadline
100	                ?? (Thread.isMainThread ? now : now.addingTimeInterval(Self.personOpenWait))
101	            deadline = limit
102	            if now >= limit { return nil }
103	            Thread.sleep(forTimeInterval: 0.05)
104	        }
105	    }
106	
107	    /// `open_project`'s refusal of a file a person's open is still reading.
108	    private static func beingOpened(_ url: URL) -> ToolError {
109	        ToolError(
110	            message: "\(url.lastPathComponent) is being opened in a window; call open_project "
111	                + "again once it has opened.")
112	    }
113	
114	    /// `open_project`'s answer when an open document already holds `url`,
115	    /// else nil. Main only.
116	    private func alreadyOpen(_ url: URL) throws -> String? {
117	        guard let existing = documentHolding(url, except: nil) else { return nil }
118	        // Bring it forward, as double-clicking an already-open document
119	        // does — otherwise `target` would still resolve a later-opened
120	        // project and the next call would edit the wrong one.
121	        existing.showWindows()
122	        return try jsonResult(["already_open": true, "project": summary(existing)])
123	    }
124	
125	    /// `new_project` — File ▸ New Project (`AppDelegate.newProject`): a blank
126	    /// 1920×1080 / 30 fps project. With `path` it is saved there straight
127	    /// away, so the agent has a file to name in later calls; without one it
128	    /// stays an untitled draft and `save_project {path}` finishes the job.
129	    /// A path another open document holds is refused BEFORE anything is
130	    /// created (spec §11 #40), so two documents never share one file.
131	    func newProject(_ a: [String: Any]) throws -> String {
132	        let url = try stringArg(a, "path").map {
133	            Self.destinationURL($0, extension: ProjectDocument.projectFileExtension)
134	        }
135	        let document = try onMain { () throws -> ProjectDocument in
136	            if let url { try self.refuseHeldPath(url, except: nil, tool: "new_project") }
137	            guard let document = try NSDocumentController.shared
138	                .openUntitledDocumentAndDisplay(true) as? ProjectDocument
139	            else {
140	                throw ToolError(message: "A new project could not be created.")
141	            }
142	            return document
143	        }
144	        guard let url else {
145	            return try onMain { try self.jsonResult(["project": self.summary(document)]) }
146	        }
147	        try save(document, to: url, operation: .saveAsOperation)
148	        return try onMain {
149	            try self.jsonResult(["saved": url.path, "project": self.summary(document)])
150	        }
151	    }
152	
153	    // MARK: - Saving
154	
155	    /// `save_project` — ⌘S. An untitled project (a movie opened as one, or a
156	    /// `new_project` with no path) has no file yet, so `path` is required for
157	    /// it and optional everywhere else; passing one writes there, the way
158	    /// Save As does — unless it names the document's own file, however
159	    /// spelled (`canonical`), which is a plain save: Save As onto itself
160	    /// would re-spell the document's path as the caller wrote it (#138). Any
161	    /// other path another open document holds is refused (spec §11 #40).
162	    func saveProject(_ a: [String: Any]) throws -> String {
163	        let document = try onMain { try self.target(a) }
164	        let existing = onMain { document.fileURL }
165	        if let path = try stringArg(a, "path") {
166	            let url = Self.destinationURL(path, extension: ProjectDocument.projectFileExtension)
167	            if let existing, Self.canonical(url.path) == Self.canonical(existing.path) {
168	                try save(document, to: existing, operation: .saveOperation)
169	                return try onMain {
170	                    try self.jsonResult(["saved": existing.path, "project": self.summary(document)])
171	                }
172	            }
173	            try onMain { try self.refuseHeldPath(url, except: document, tool: "save_project") }
174	            try save(document, to: url, operation: .saveAsOperation)
175	            return try onMain {
176	                try self.jsonResult(["saved": url.path, "project": self.summary(document)])
177	            }
178	        }
179	        guard let url = existing else {
180	            throw ToolError(
181	                message: "This project has never been saved, so save_project needs a path — "
182	                    + "an absolute path ending in .\(ProjectDocument.projectFileExtension).")
183	        }
184	        try save(document, to: url, operation: .saveOperation)
185	        return try onMain {
186	            try self.jsonResult(["saved": url.path, "project": self.summary(document)])
187	        }
188	    }
189	
190	    /// The open document whose file is `url` — the path `get_project` reports
191	    /// for it, `fileURL` or the movie it was built from — compared exactly and
192	    /// canonically, as `target(_:)` compares: two spellings of one file that
193	    /// failed to match would put two documents at one path. `except` is
194	    /// skipped (`===`), for a save that is that document's own. Main only.
195	    func documentHolding(_ url: URL, except: ProjectDocument?) -> ProjectDocument? {
196	        let canonical = Self.canonical(url.path)
197	        return openProjects().first { document in
198	            if let except, document === except { return false }
199	            guard let open = Self.path(of: document) else { return false }
200	            return open == url.path || Self.canonical(open) == canonical
201	        }
202	    }
203	
204	    /// Refuses a write to a path another open document holds (spec §11 #40),
205	    /// naming that document and the way out, and then to a path a person's
206	    /// open is still reading (spec §11 #234). Main only, so `save_project`
207	    /// and `new_project` call it inside `onMain`. The save is a later hop:
208	    /// an open that begins after this check is not seen (#234's risks).
209	    func refuseHeldPath(_ url: URL, except: ProjectDocument?, tool: String) throws {
210	        if let holder = documentHolding(url, except: except) {
211	            throw ToolError(
212	                message: "Another open project (\(holder.displayName ?? "Untitled")) is at "
213	                    + "\(url.path), so \(tool) did not write there: close_project closes it, "
214	                    + "or pass another path.")
215	        }
216	        guard ProjectDocumentController.isOpening(url) else { return }
217	        throw ToolError(
218	            message: "\(url.path) is being opened in a window, so \(tool) did not write "
219	                + "there: call \(tool) again once it has opened, or pass another path.")
220	    }
221	
222	    /// Writes `document` and WAITS for NSDocument's asynchronous save to
223	    /// finish, so the tool's answer is only sent once the package is really on
224	    /// disk and the agent can read it back.
225	    ///
226	    /// The wait is why `save_project` and `new_project` run on the server
227	    /// thread: `save(to:ofType:for:completionHandler:)` delivers its
228	    /// completion on the MAIN thread, which a main-thread wait would be
229	    /// occupying.
230	    func save(
231	        _ document: ProjectDocument, to url: URL, operation: NSDocument.SaveOperationType
232	    ) throws {
233	        guard !Thread.isMainThread else {
234	            throw ToolError(message: "Saving cannot run on the main thread.")
235	        }
236	        let semaphore = DispatchSemaphore(value: 0)
237	        let box = AgentBox<(any Error)?>()
238	        onMain {
239	            document.save(
240	                to: url, ofType: ProjectDocument.projectTypeIdentifier, for: operation
241	            ) { error in
242	                box.value = error
243	                semaphore.signal()
244	            }
245	        }
246	        guard semaphore.wait(timeout: .now() + 120) == .success else {
247	            throw ToolError(message: "Timed out saving \(url.lastPathComponent).")
248	        }
249	        if let error = box.value ?? nil {
250	            throw ToolError(message: error.localizedDescription)
251	        }
252	    }
253	
254	    // MARK: - Closing
255	
256	    /// `close_project` — File ▸ Close (⌘W; spec §11 #40). It runs on main,
257	    /// as the menu item does, and closes through `ProjectDocument.close()`,
258	    /// which releases the recipe key and the graphic store; it never writes
259	    /// the package. A window with a sheet attached is refused first, because
260	    /// the sheet is window-modal work in progress (`handleEditorKey`'s rule);
261	    /// then unsaved changes, unless `discard: true`. Under autosave in place
262	    /// "unsaved" means "not yet autosaved", and that is all `discard` loses.
263	    func closeProject(_ a: [String: Any]) throws -> String {
264	        let discard = try boolArg(a, "discard") ?? false
265	        let document = try target(a)
266	        let name = document.displayName ?? "Untitled"
267	        let path = Self.path(of: document)
268	        let edited = document.isDocumentEdited
269	        if document.windowControllers.contains(where: { $0.window?.attachedSheet != nil }) {
270	            throw ToolError(
271	                message: "\(name) has a sheet open on its window, so close_project left it "
272	                    + "open: finish or cancel the sheet first.")
273	        }
274	        if edited && !discard {
275	            throw ToolError(
276	                message: "\(name) has unsaved changes, so close_project left it open: "
277	                    + "save_project saves them, or close_project with discard: true closes "
278	                    + "it and loses them.")
279	        }
280	        document.close()
281	        return try jsonResult(
282	            [
283	                "ok": true, "closed": name, "path": path ?? NSNull(),
284	                "discarded_changes": edited,
285	            ])
286	    }
287	
288	    // MARK: - Reading
289	
290	    /// `get_project` — the whole project as the JSON of spec §5.2, straight
291	    /// from the core (`rc_project_to_json`), plus the view state that is
292	    /// deliberately NOT in the model: the playhead, the selection and the
293	    /// in/out range live in Swift (§5.2's last bullet).
294	    func getProject(_ a: [String: Any]) throws -> String {
295	        let document = try target(a)
296	        // The EDITED project (road map 2's phase 9): with a nest open
297	        // (`set_scope`) this reports the nest as a project — its tracks and
298	        // clips at the top level, its frozen size as the canvas — which is
299	        // what the app is showing and what a scoped op's ids resolve
300	        // against, so an agent reads the ids it is about to name. With no
301	        // nest open it is the same handle it always was, byte for byte.
302	        let project = document.editedProject
303	        var result: [String: Any] = [:]
304	        if let data = project.json.data(using: .utf8),
305	            let object = (try? JSONSerialization.jsonObject(with: data)) as? [String: Any] {
306	            result["project"] = object
307	        } else {
308	            result["project_json"] = project.json
309	        }
310	        result["path"] = Self.path(of: document) ?? NSNull()
311	        result["name"] = document.displayName ?? "Untitled"
312	        result["unsaved_changes"] = document.isDocumentEdited
313	        result["duration"] = project.duration
314	        result["playhead"] = document.playhead
315	        result["selection"] = document.selection.sorted().map { Int($0) }
316	        if let range = document.inOutRange {
317	            result["in_out_range"] = ["start": range.start, "end": range.end]
318	        }
319	        result.merge(scopeReport(document)) { _, new in new }
320	        let missing = document.missingMedia.map { Int($0.id) }
321	        if !missing.isEmpty { result["missing_media"] = missing }
322	        result["graphics"] = graphicsSummary(document)
323	        result["note"] =
324	            "Times are ticks at 600000 per second. tracks[0] is the BACK of the layer stack; "
325	            + "clip ids, track ids, marker ids and media ids share one number space."
326	        if document.scope != nil {
327	            result["note"] =
328	                (result["note"] as? String ?? "")
329	                + " A nest is OPEN (set_scope), so project is that NEST seen as a project: its "
330	                + "own tracks and clips at the top level, its frozen size as the canvas, times "
331	                + "from its own zero, no markers, and its own row under nests deliberately "
332	                + "emptied because its contents are the top level here. media and nests are "
333	                + "still the document's — one id space. Send scope with an op to edit in here; "
334	                + "set_scope with no arguments comes back out."
335	        }
336	        return try jsonResult(result)
337	    }
338	
339	    // MARK: - Transport
340	
341	    /// `set_playhead` — clicking the ruler / the transport keys. View state,
342	    /// not an edit: no op runs and no undo step is registered (spec §5.2). It
343	    /// goes through `EditorViewController.setPlayhead` when the project has a
344	    /// window, so the player seeks and every pane follows; a windowless
345	    /// document just gets the time, which is all `render_frame` needs.
346	    func setPlayhead(_ a: [String: Any]) throws -> String {
347	        let document = try target(a)
348	        let time = try timeArg(a, "t", document)
349	        let clamped = max(0, time)
350	        if let editor = editor(document) {
351	            editor.setPlayhead(clamped)
352	            editor.viewStateDidChange()
353	        } else {
354	            document.playhead = clamped
355	        }
356	        return try jsonResult(
357	            ["ok": true, "playhead": document.playhead, "project": summary(document)])
358	    }
359	
360	    /// `set_range` — Mark ▸ Set In / Set Out / Clear Range (I, O, ⌥X:
361	    /// `EditorViewController.setInPoint` / `setOutPoint` /
362	    /// `clearInOutRange`). View state like the playhead, so no op runs and
363	    /// nothing is undoable — but `export {range: "in_out"}` reads it, and
364	    /// `get_project` already reported it, so this is the write half of a
365	    /// field the agent could previously only look at.
366	    ///
367	    /// With neither bound the range is CLEARED, which is what ⌥X does.
368	    func setRange(_ a: [String: Any]) throws -> String {
369	        let document = try target(a)
370	        let start = try optionalTimeArg(a, "start", document)
371	        let end = try optionalTimeArg(a, "end", document)
372	        if start == nil && end == nil {
373	            document.inOutRange = nil
374	        } else {
375	            let from = max(0, start ?? document.inOutRange?.start ?? 0)
376	            let to = max(0, end ?? document.inOutRange?.end ?? document.project.duration)
377	            guard to > from else {
378	                throw ToolError(
379	                    message: "The range end (\(to)) must be after its start (\(from)); "
380	                        + "call set_range with no arguments to clear it.")
381	            }
382	            document.inOutRange = (start: from, end: to)
383	        }
384	        if let editor = editor(document) {
385	            editor.viewStateDidChange()
386	            editor.applyLoopRange()
387	        }
388	        var result: [String: Any] = ["ok": true, "project": summary(document)]
389	        if let range = document.inOutRange {
390	            result["in_out_range"] = ["start": range.start, "end": range.end]
391	        } else {
392	            result["in_out_range"] = NSNull()
393	        }
394	        return try jsonResult(result)
395	    }
396	
397	    /// `set_selection` — clicking a clip in the timeline
398	    /// (`EditorViewController+Timeline.timelineSelected`) or on the canvas
399	    /// (`+Canvas.canvasSelected`), and Edit ▸ Select All / Select Forward
400	    /// (`selectAll(_:)`, `selectAfterPlayhead(_:)`). View state like the
401	    /// playhead and the range: no op runs and nothing is undoable.
402	    ///
403	    /// It is the write half of a field `get_project` already reported, and
404	    /// the one the agent was missing: the canvas handles, crop mode and
405	    /// every inspector pane act on the SELECTION, so without this nothing
406	    /// they do could be driven or checked by driving the app — which is why
407	    /// spec §10 step 8 stayed unverified.
408	    ///
409	    /// **Its ids mean the OPEN container** (road map 2's phase 9), and it
410	    /// gets that from `clipsArg` without a line of its own: a selection is
411	    /// clip ids in whichever container the app is looking at
412	    /// (`ProjectDocument.setNestPath` moves the two together), so with a nest
413	    /// open this selects inside it and cannot name a clip on the timeline.
414	    /// That is the same rule `effectiveScope` gives every other tool, read
415	    /// for a tool that has no `scope` argument of its own to override it
416	    /// with — the way in is `set_scope`, which is where a view is chosen.
417	    func setSelection(_ a: [String: Any]) throws -> String {
418	        let document = try target(a)
419	        var ids: [UInt32] = []
420	        if let raw = a["clips"], !(raw is NSNull) {
421	            // An explicit `[]` means "select nothing", which is a real
422	            // intent here — unlike an OP over no clips, the mistake
423	            // `optionalClipsArg` refuses an empty list as. Omitting `clips`
424	            // does the same, the way `set_range` with no bounds clears the
425	            // range.
426	            if let array = raw as? [Any], array.isEmpty {
427	                ids = []
428	            } else {
429	                ids = try clipsArg(a, "clips", document)
430	            }
431	        }
432	        // `clipsArg` validating every id against the snapshot is the ONLY
433	        // thing keeping a dead id out of the selection: `viewStateDidChange`
434	        // republishes the view state but does not run
435	        // `ProjectDocument.clampViewState`, which prunes on a MODEL change,
436	        // so nothing downstream will notice one.
437	        document.selection = Set(ids)
438	        if let editor = editor(document) {
439	            editor.viewStateDidChange()
440	        }
441	        return try jsonResult(
442	            [
443	                "ok": true,
444	                "selection": document.selection.sorted().map { Int($0) },
445	                "project": summary(document),
446	            ])
447	    }
448	}
449	import AppKit
450	
451	/// `new_project_from_range` (spec §11 CJ-52; road map "creator-jobs" CJ5b),
452	/// mirroring File ▸ New Project from Range…
453	/// (`EditorViewController+NewFromRange.swift`): the top-level timeline's
454	/// `[from, to)` opened as a new project through `ProjectDocument.derived(…)`,
455	/// with the kept media's caches and the drawn graphics carried. Saved at
456	/// `path` when given, as `new_project` saves; untitled and dirty otherwise.
457	/// The source document never changes, so it makes no undo step there.
458	extension AgentServer {
459	
460	    /// Runs on the server thread (`creatorOffMainTools`), its body one main
461	    /// hop: the target, the nest refusal, the times, the path's refusals,
462	    /// then the door.
463	    func newProjectFromRange(_ a: [String: Any]) throws -> String {
464	        guard !Thread.isMainThread else {
465	            throw ToolError(
466	                message: "new_project_from_range must run on the server thread — its name is "
467	                    + "missing from AgentServer.creatorOffMainTools.")
468	        }
469	        let path = try stringArg(a, "path")
470	        let display = Self.derivedDisplay
471	        return try onMain {
472	            let document = try target(a)
473	            guard document.scope == nil else {
474	                throw ToolError(
475	                    message: "new_project_from_range works on the top-level timeline: set_scope "
476	                        + "with no nest first.")
477	            }
478	            let from = try timeArg(a, "from", document)
479	            let to = try timeArg(a, "to", document)
480	            let url = path.map {
481	                Self.destinationURL($0, extension: ProjectDocument.projectFileExtension)
482	            }
483	            if let url {
484	                try refuseHeldPath(url, except: nil, tool: "new_project_from_range")
485	                guard !FileManager.default.fileExists(atPath: url.path) else {
486	                    throw ToolError(
487	                        message: "\(url.path) already exists, so new_project_from_range did not "
488	                            + "write there: pass a new path.")
489	                }
490	            }
491	            let made: (document: ProjectDocument, carried: DerivedCarry.Report)
492	            do {
493	                made = try ProjectDocument.derived(
494	                    from: document, handle: document.project, range: (from: from, to: to),
495	                    path: url, display: display, name: "\(document.displayStem) (range)")
496	            } catch {
497	                throw ToolError(message: error.localizedDescription)
498	            }
499	            var result: [String: Any] = [
500	                "project": summary(made.document),
501	                "carried": [
502	                    "files": made.carried.files, "bytes": made.carried.bytes,
