528	/// The agent's mirrors of Edit ▸ Undo (⌘Z) and Edit ▸ Redo (⇧⌘Z).
529	///
530	/// Every other agent tool is an edit, and `ProjectDocument.performGroupedEdit`
531	/// already turns each one into exactly one undo step (app/CLAUDE.md). Without
532	/// these two the agent could make those steps and never walk them, so the one
533	/// property the whole undo design rests on — one edit is one step, and undoing
534	/// it restores the frame — could not be checked by driving the built app,
535	/// which spec §10 step 7 asks for.
536	extension AgentServer {
537	
538	    /// `undo` — Edit ▸ Undo. One step, and the step's action name comes back
539	    /// so a caller can see what it walked past.
540	    func undoEdit(_ a: [String: Any]) throws -> String {
541	        try walkHistory(a, redo: false)
542	    }
543	
544	    /// `redo` — Edit ▸ Redo.
545	    func redoEdit(_ a: [String: Any]) throws -> String {
546	        try walkHistory(a, redo: true)
547	    }
548	
549	    /// **Pitfall** (app/CLAUDE.md, and the same one `performGroupedEdit`
550	    /// documents): a tool call is not an AppKit event, so with `groupsByEvent`
551	    /// on, `NSUndoManager` opens an implicit per-event group that nothing ever
552	    /// closes. `undo()` closes the top-level group before undoing, which
553	    /// against that phantom group leaves an end with no begin and hangs the
554	    /// next save inside its file coordinator. Turning event grouping off for
555	    /// the duration — never "flushing" the level — is the same discipline
556	    /// every off-event path here follows.
557	    private func walkHistory(_ a: [String: Any], redo: Bool) throws -> String {
558	        let document = try target(a)
559	        guard let manager = document.undoManager else {
560	            throw ToolError(message: "This project has no undo history.")
561	        }
562	        guard redo ? manager.canRedo : manager.canUndo else {
563	            throw ToolError(
564	                message: redo
565	                    ? "There is nothing to redo. Only an undo makes a redo step."
566	                    : "There is nothing to undo. Only an edit makes an undo step; "
567	                        + "set_playhead and set_range are view state and make none.")
568	        }
569	        let name = (redo ? manager.redoActionName : manager.undoActionName)
570	        let groupsByEvent = manager.groupsByEvent
571	        if groupsByEvent { manager.groupsByEvent = false }
572	        if redo { manager.redo() } else { manager.undo() }
573	        if groupsByEvent { manager.groupsByEvent = true }
574	        return try jsonResult([
575	            "ok": true,
576	            redo ? "redone" : "undone": name.isEmpty ? "Edit" : name,
577	            "can_undo": manager.canUndo,
578	            "can_redo": manager.canRedo,
579	            "project": summary(document),
580	        ])
581	    }
582	}
