585	/// Editing INSIDE a nest over MCP, and looking inside one: the envelope's
586	/// `scope` (spec §6, `core/src/scope.rs`) and the `set_scope` tool that
587	/// mirrors the double-click (road map 2's phase 9).
588	///
589	/// **The whole surface is arguments on tools that already existed.** No op
590	/// was added — `rc_op_names` was unchanged — so the catalog grew one property,
591	/// injected once in `AgentCatalog.tool` for every name the core calls an op,
592	/// and one tool, which is not an op either. What that buys is the thing the
593	/// spec designed and left (§4.4): every row of §6 can now name a clip, a
594	/// track or an action inside a nest.
595	///
596	/// Three pieces, and the split between them is the point:
597	///
598	///  - **The scope is read ONCE, at the dispatch.** `AgentServer.dispatch` is
599	///    the only place holding both a tool's name and its arguments for all
600	///    seventy-five of them, so it reads `scope` there and leaves it on
601	///    `callScope` for the length of the call; `performGroupedEdit` stamps it
602	///    onto every op through `addressed` below. Fifty-eight handlers were not
603	///    touched and cannot forget.
604	///  - **The id readers resolve against a CONTAINER.** `idScope` below is what
605	///    `clipArg`, `clipsArg`, `optionalClipsArg` and `trackArg` ask, so
606	///    `trim_start {clip: <inside the nest>, scope: 4}` finds its clip instead
607	///    of being refused by the app before the core ever saw the scope. That
608	///    was the real work of this phase on this side, and the road map does not
609	///    mention it.
610	///  - **`set_scope` is view state and edits nothing**, exactly like
611	///    `set_playhead`, `set_range` and `set_selection`. It exists because
612	///    `get_project` and `render_frame` answer about what the app is LOOKING
613	///    at, and without it there was no way to make them look inside. An op
614	///    sent while it is open follows it unless it carries a `scope` of its
615	///    own — `effectiveScope` below is that rule and argues it.
616	///
617	/// **Two composites take no scope ARGUMENT and still work inside a nest**,
618	/// and the ops-only injection rule excludes them without an exception list:
619	/// `detect_silence` and `normalize_clip` are not §6 rows. They follow the
620	/// VIEW instead, from both ends at once — their ids resolve through
621	/// `idScope` like every other tool's, and `SilenceDetector.read` /
622	/// `AudioNormalize.read` compute from `ProjectDocument.editedProject`'s plan,
623	/// which is the same container — so the pair is coherent rather than half
624	/// converted. What they cannot do is be pointed at a nest nobody is looking
625	/// at, and that is the argument for leaving it there: each one measures a
626	/// PLAN, the app memoises exactly one scoped handle (the open one), and a
627	/// per-call `scope` would mean building a second project per call and
628	/// mapping every tick in the answer back out of it. Nothing is lost that a
629	/// caller cannot reach — `set_scope`, then ask — and `ripple_delete_ranges`,
630	/// which is what `detect_silence`'s answer is fed to, takes a scope like any
631	/// other op.
632	///
633	/// There is also a spelling hazard here worth naming, since it is the reason
634	/// to think twice before changing that: `detect_silence` already answers a
635	/// RESULT key called `scope`, meaning which set of CLIPS it measured.
636	/// Nothing keeps those two words apart but the fact that one is an input and
637	/// the other an answer, so a `detect_silence` that ever took the envelope's
638	/// scope would have to say in both descriptions which is which.
639	///
640	/// **The captions group used to be the one place this did NOT line up, and
641	/// the way it was settled is the rule for the next producer.** Every one of
642	/// them — `CaptionImporter.plan(for:in:)`, `Transcriber`,
643	/// `TranscribeSheetController` and `CaptionExporter`, on the File-menu path
644	/// and the tool path alike — built its plan from `document.project`, the
645	/// DOCUMENT, while the ops that plan produced were addressed to whatever nest
646	/// was open, here and in `ProjectDocument.addressed(_:)` alike. So with a nest
647	/// open they measured a placement against the timeline and then placed it
648	/// inside the nest, and the menu item had exactly the same defect as the tool.
649	/// All four read `editedProject` now, as `SilenceDetector` and
650	/// `AudioNormalize` do. **A producer reads the container it writes into** —
651	/// that is the whole rule, it is cheaper than making the ops document-level,
652	/// and it is what a fifth producer should copy.
653	extension AgentServer {
654	
655	    // MARK: - The call's scope
656	
657	    /// Refuses a `scope` that names no nest in `document`, by name.
658	    ///
659	    /// Called from `target(_:)`, which every handler passes through before it
660	    /// reads a single argument, so the ORDER `core/src/scope.rs` documents
661	    /// holds on this side too: an unknown nest is answered FIRST, ahead of
662	    /// the op's own arguments, because it is the argument that decides which
663	    /// container the caller thinks it is editing.
664	    ///
665	    /// The sentence is the CORE's, word for word, with the app's own
666	    /// direction added after it. Both layers can answer this — the app for
667	    /// every op tool, the core for anything that reaches it another way — and
668	    /// a caller (or a proof) that learns one spelling should not have to
669	    /// learn a second.
670	    func checkCallScope(_ document: ProjectDocument) throws {
671	        guard let scope = callScope else { return }
672	        guard document.project.snapshot.nest(scope) != nil else {
673	            throw ToolError(
674	                message: "no nest with id \(scope). get_project lists them under nests, and a "
675	                    + "nest clip's source.project names the one it shows.")
676	        }
677	    }
678	
679	    /// The container this call's id arguments resolve in: the timeline, or
680	    /// the nest the envelope's `scope` named.
681	    ///
682	    /// It reads the PARENT snapshot rather than building a scoped handle,
683	    /// which is the cheap half of `core/src/scope.rs`'s view and the only
684	    /// half an id lookup needs: a nest holds its tracks and clips in the
685	    /// parent's one id space (spec §5.2), so `snapshot.nests[]` already has
686	    /// them. `NestScope` next door reads the path the same way and for the
687	    /// same reason.
688	    /// The nest a call is really acting in: its own `scope` when it has one,
689	    /// else the nest the APP has open (`set_scope`), else nil.
690	    ///
691	    /// **The argument overrides the view; an absent argument follows it.**
692	    /// That is the whole rule, and it is the one that makes every other piece
693	    /// agree with itself. `get_project` reports the open container, so the
694	    /// ids a caller reads back are that container's; `render_frame` draws it;
695	    /// `detect_silence`, `normalize_clip` and `sync_audio` compute from
696	    /// `ProjectDocument.editedProject`'s plan, which is that container's too;
697	    /// and `ProjectDocument.addressed(_:)` already stamps the open nest onto
698	    /// every op the APP sends, so an agent that inherits it is doing exactly
699	    /// what the person at the keyboard does. The alternative — the argument
700	    /// or nothing — was written first and thrown away: it made
701	    /// `get_project` list clips that the very next op could not name, and it
702	    /// would have left the three composites resolving their ids in one
703	    /// container and reading their plan from another.
704	    ///
705	    /// What it costs is the spelling of "edit the timeline while I am looking
706	    /// inside a nest", which is now `set_scope` with no arguments first. That
707	    /// is the same thing the UI costs a person, and it is worth less than the
708	    /// coherence.
709	    func effectiveScope(_ document: ProjectDocument) -> UInt32? {
710	        callScope ?? document.scope
711	    }
712	
713	    /// The container this call's id arguments resolve in — `effectiveScope`'s
714	    /// nest, or the timeline.
715	    ///
716	    /// It reads the PARENT snapshot rather than building a scoped handle,
717	    /// which is the cheap half of `core/src/scope.rs`'s view and the only
718	    /// half an id lookup needs: a nest holds its tracks and clips in the
719	    /// parent's one id space (spec §5.2), so `snapshot.nests[]` already has
720	    /// them. `NestScope` next door reads the path the same way and for the
721	    /// same reason.
722	    func idScope(_ document: ProjectDocument) throws -> AgentIdScope {
723	        let snapshot = document.project.snapshot
724	        guard let scope = effectiveScope(document) else {
725	            return AgentIdScope(
726	                nest: nil, clips: snapshot.clips, tracks: snapshot.tracks, fromArgument: false)
727	        }
728	        // Unreachable through `target(_:)`, which has already refused an
729	        // unknown `scope` argument, and through `clampViewState`, which
730	        // clears a view path whose nest has gone. It is here so the function
731	        // is total rather than optional-returning: a reader that fell back to
732	        // the timeline when the nest was missing would answer "No clip has id
733	        // 17" for a call whose real mistake was the scope.
734	        guard let nest = snapshot.nest(scope) else {
735	            try checkCallScope(document)
736	            return AgentIdScope(
737	                nest: nil, clips: snapshot.clips, tracks: snapshot.tracks, fromArgument: false)
738	        }
739	        return AgentIdScope(
740	            nest: nest, clips: nest.clips, tracks: nest.tracks, fromArgument: callScope != nil)
741	    }
742	
743	    /// The scope stamped onto the ops of one agent edit — `performGroupedEdit`
744	    /// in the frozen file calls this, and it is the MCP mirror of
745	    /// `ProjectDocument.addressed(_:)`.
746	    ///
747	    /// **Two rules, and the difference between them is deliberate.** An
748	    /// EXPLICIT `scope` is stamped on every op, the seven document-level ones
749	    /// included, so an agent that asks for `add_media {scope: 4}` gets the
750	    /// core's own refusal by name rather than a silent redirection — it asked
751	    /// a question and the answer is no (`ReelOp.documentLevelNames` argues
752	    /// the other half of this). An INHERITED one skips them, exactly as
753	    /// `addressed` does, because a Finder drop inside a nest is an
754	    /// `add_media` on the document's one media list plus an `add_clip` in the
755	    /// nest, and an agent's `import_media` inside a nest is the same act.
756	    ///
757	    /// **Two of those seven may not be sent that way at all**, and
758	    /// `checkDocumentLevelTicks` below is the refusal: `add_marker` and a
759	    /// `set_marker` carrying a `time` would reach the timeline's `markers[]`
760	    /// at a tick the caller measured from the NEST's zero. Read the two
761	    /// together — this method decides which container an op is addressed to,
762	    /// and that one decides which ops may take the unscoped answer.
763	    ///
764	    /// It mirrors that method rather than calling it because `addressed` is
765	    /// private to `ProjectDocument` — but the two must not drift, and the
766	    /// reason is not tidiness: `AgentServer.performGroupedEdit` TRIES the ops
767	    /// on the handle first, purely, to turn a refusal into a message instead
768	    /// of a beep, and a trial addressed differently from the commit would
769	    /// report a failure the commit would not have had.
770	    func addressed(_ ops: [ReelOp], _ document: ProjectDocument) -> [ReelOp] {
771	        if let scope = callScope { return ops.map { $0.scoped(scope) } }
772	        guard let view = document.scope else { return ops }
773	        return ops.map { $0.isDocumentLevel ? $0 : $0.scoped(view) }
774	    }
775	
776	    /// Refuses the ops an INHERITED scope would send at a tick measured from
777	    /// the wrong zero — `add_marker`, and `set_marker`'s `time`.
778	    ///
779	    /// **This is the tool path's copy of a decision the app made first.**
780	    /// `addressed` above sends the seven document-level ops UNSCOPED out of a
781	    /// scope it inherited, so `core/src/scope.rs`'s `refused_inside` never
782	    /// fires for them and they land on the document. For five of the seven
783	    /// that is exactly right, and it is why File ▸ Add Media…, a Relink, a
784	    /// Remove and the Document tab's canvas rows all go on working with a nest
785	    /// open. For the two that carry a TICK it is a wrong PLACEMENT reported as
786	    /// success: while a scope is open `ProjectDocument.playhead` is
787	    /// NEST-LOCAL, `get_project` answers the nest's clips and duration,
788	    /// `set_playhead` writes the nest's own time and `render_frame` draws the
789	    /// nest — so a caller working in the open container hands over a
790	    /// nest-local tick and the marker appears somewhere else on the timeline,
791	    /// with an `ok` on it. The app decided this already:
792	    /// `EditorViewController+NestScope.validateNestScopeAction` greys Add
793	    /// Marker out inside a nest and `addMarkerCommand` carries its own guard
794	    /// for the bare-M key, both for this exact reason. This is that refusal,
795	    /// worded for a caller who gets a sentence rather than a dead menu item.
796	    ///
797	    /// **`remove_marker` is deliberately NOT here, and neither is a
798	    /// `set_marker` that carries no `time`.** Both name an id and read no
799	    /// clock, so there is no zero for either to be measured from — and both
800	    /// are LIVE in the app with a nest open, in the Document tab's marker
801	    /// table, which is about the FILE and reads `documentSnapshot` for that
802	    /// very reason (app/CLAUDE.md). Refusing them would make these tools less
803	    /// of a mirror of the UI than they already are, and would charge a rename
804	    /// two `set_scope` calls and a re-entry for nothing. That the marker id is
805	    /// the DOCUMENT's is already settled and already said: `markerArg` resolves
806	    /// it against the timeline's markers on purpose, so that the core's own
807	    /// sentence rather than "No marker has id 12" is what a scoped call hears.
808	    ///
809	    /// An EXPLICIT `scope` is left alone. It is stamped on all seven and the
810	    /// core answers `"add_marker has no meaning inside nest N"` by name, which
811	    /// is the designed answer to a caller that asked the question outright
812	    /// (`addressed`'s two rules, and `ReelOp.documentLevelNames`).
813	    ///
814	    /// It is called from `AgentServer.performGroupedEdit` — the one place
815	    /// every editing tool passes through, the handlers that call it directly
816	    /// rather than through `editResult` included — so no handler has to
817	    /// remember it and a later composite that builds a marker op inherits it.
818	    /// What being there rather than at the two handlers' heads costs is the
819	    /// ORDER of one refusal: a call whose `at` is ALSO unreadable hears about
820	    /// the `at` first, because the handler reads its arguments before it
821	    /// reaches the edit. That is a true complaint either way, which is what
822	    /// makes it a fair price here and not in `checkCallScope`'s case — there
823	    /// the mistake being reported is which document the caller thinks it is
824	    /// editing, and it outranks everything.
825	    func checkDocumentLevelTicks(_ ops: [ReelOp], _ document: ProjectDocument) throws {
826	        guard callScope == nil, let view = document.scope else { return }
827	        for op in ops {
828	            switch op.name {
829	            case "add_marker":
830	                throw ToolError(
831	                    message: "add_marker has no meaning inside nest \(view): a nest has no "
832	                        + "markers, and every tick in this call is measured from that nest's "
833	                        + "own zero, so the marker would land somewhere else on the timeline. "
834	                        + "set_scope with no arguments comes back out; then add_marker at a "
835	                        + "project time. The app greys Add Marker out in here for the same "
836	                        + "reason.")
837	            case "set_marker" where op.args["time"] != nil:
838	                throw ToolError(
839	                    message: "set_marker's time has no meaning inside nest \(view): a marker's "
840	                        + "time is the timeline's, and every tick in this call is measured "
841	                        + "from that nest's own zero. set_scope with no arguments comes back "
842	                        + "out; then set_marker at a project time. Its name, chapter and color "
843	                        + "mean the same thing in either container and are accepted in here, "
844	                        + "which is what the Document tab's marker table does with a nest "
845	                        + "open.")
846	            default:
847	                continue
848	            }
849	        }
850	    }
851	
852	    /// Where an edit's ops actually LANDED, as the result reports it: the nest
853	    /// whose id was stamped on them, and the names of any that went to the
854	    /// document instead.
855	    ///
856	    /// **It is read off what `addressed` STAMPS and never off
857	    /// `effectiveScope`**, and that difference is the whole reason it exists.
858	    /// `editResult` used to echo the effective scope unconditionally, which is
859	    /// a statement about the VIEW; `addressed` sends the seven document-level
860	    /// ops unscoped out of an inherited one, which is a statement about the
861	    /// EDIT. So a `remove_media`, a `set_canvas` or a marker rename sent with
862	    /// a nest open reported that it had landed inside that nest when it had
863	    /// landed on the document — a tool misreporting WHERE an edit went, which
864	    /// is the class of defect this phase already fixed once at the merge seam
865	    /// (`performGroupedEdit`'s closing guard).
866	    ///
867	    /// **The MIXED edit is why `document_ops` is a list and not a flag.** One
868	    /// edit can legitimately span both containers — a Finder drop inside a
869	    /// nest is `add_media` on the document plus `add_clip` in the nest, as ONE
870	    /// undo step (`ReelOp.documentLevelNames` argues it) — and there is no
871	    /// single number that describes that, which is exactly the mistake being
872	    /// fixed. So both halves are named: `scope` is the nest the scoped ops
873	    /// carried and `document_ops` is every op that skipped it, and a result
874	    /// carrying both says which of its ops went where. No tool sends such a
875	    /// mix TODAY — an agent's `import_media` and `add_clip` are two calls, and
876	    /// `add_background`'s Image… composite is the menu's rather than the
877	    /// tool's — but the account has to be right before the composite that does
878	    /// arrives, and nobody reading one of these results should have to know
879	    /// which handlers mix and which do not.
880	    ///
881	    /// With no scope anywhere it answers nothing at all, so every ordinary
882	    /// result is byte for byte the one it always was.
883	    func scopeLanding(_ ops: [ReelOp], _ document: ProjectDocument) -> [String: Any] {
884	        guard effectiveScope(document) != nil else { return [:] }
885	        let stamped = addressed(ops, document)
886	        var result: [String: Any] = [:]
887	        // Uniform by construction: `addressed` stamps ONE scope on every op it
888	        // stamps at all, so the first one found is the answer for all of them.
889	        if let nest = stamped.compactMap({ $0.scope }).first { result["scope"] = Int(nest) }
890	        let onDocument = stamped.filter { $0.scope == nil }.map { $0.name }
891	        if !onDocument.isEmpty { result["document_ops"] = onDocument }
892	        return result
893	    }
894	
895	    // MARK: - The startup parity check's fourth part
896	
897	    /// Part 4 of `AgentServer.catalogParityFailure`: every OP tool declares
898	    /// the envelope's `scope`.
899	    ///
900	    /// **It is here because parts 1 to 3 cannot see an OMISSION.** They
901	    /// compare name SETS and read each schema's shape, so a tool that quietly
902	    /// lacks an argument passes all three — and a scope-less op tool is
903	    /// exactly that: the server starts clean, the op works on the timeline,
904	    /// and editing inside a nest is unreachable through it with nothing
905	    /// anywhere saying so. `AgentCatalog.tool`'s injection makes that hard to
906	    /// do by hand, but the fifty-sixth op arriving with a hand-written schema,
907	    /// or an `opNames` that came back short, both land here.
908	    ///
909	    /// It reads the CATALOG rather than asking whether the injection ran,
910	    /// which is the only way it can catch anything: a check that asked
911	    /// `AgentCatalog.tool` about itself would be testing the check. Members
912	    /// of `opsWithoutTools` are skipped for part 2's reason — there is no
913	    /// tool to declare anything. It costs nothing to run: the tools array is
914	    /// already parsed and the op list already read.
915	    static func scopeFailure(_ tools: [[String: Any]], _ ops: Set<String>) -> String? {
916	        let scopeless =
917	            tools
918	            .filter { tool in
919	                guard let name = tool["name"] as? String, ops.contains(name) else { return false }
920	                let properties = (tool["inputSchema"] as? [String: Any])?["properties"]
921	                    as? [String: Any]
922	                return properties?["scope"] == nil
923	            }
924	            .compactMap { $0["name"] as? String }.sorted()
925	        guard scopeless.isEmpty else {
926	            return "these op tools do not declare scope: \(scopeless) — every row of spec §6 "
927	                + "can be sent inside a nest (core/src/scope.rs), and a tool that does not "
928	                + "say so is one an agent cannot use in there"
929	        }
930	        return nil
931	    }
932	
933	    // MARK: - set_scope
934	
935	    /// `set_scope` — double-clicking a nest clip, Clip ▸ Open Nest (⌘↓) and
936	    /// Clip ▸ Close Nest (⌘↑) (`EditorViewController+NestScope.swift`).
937	    ///
938	    /// View state like the playhead, the range and the selection: no op runs,
939	    /// nothing is undoable and the project is untouched. What it moves is
940	    /// what `get_project` reports and `render_frame` draws, which is the only
941	    /// way an agent can SEE what an edit inside a nest did.
942	    ///
943	    /// **It is ABSOLUTE**, like the other three `set_` tools: the argument
944	    /// names where to BE, not a step to take, so `set_scope {clip: 41}` means
945	    /// the same thing from the timeline and from three levels down. That is
946	    /// what makes it usable without first reading the current scope back —
947	    /// and it is why `clip` accepts a nest clip in ANY container, since the
948	    /// path down to a given id is determined (one id space, and a nest cannot
949	    /// show itself at any remove).
950	    func setScope(_ a: [String: Any]) throws -> String {
951	        let document = try target(a)
952	        let path = try nestScopePath(a, document)
953	        applyNestScope(path, document)
954	        var result: [String: Any] = ["ok": true]
955	        result.merge(scopeReport(document)) { _, new in new }
956	        result["playhead"] = document.playhead
957	        result["project"] = summary(document)
958	        return try jsonResult(result)
959	    }
960	
961	    /// `set_scope`'s two arguments read into the path they name.
962	    ///
963	    /// `nest` and `clip` are two spellings of one destination and at most one
964	    /// may be given; neither means the timeline. They are not interchangeable
965	    /// and the tool says so: `clip` names the nest AND the start the times
966	    /// inside are measured from, which is what a double-click has and what
967	    /// two clips showing one nest do not share, while `nest` is the number an
968	    /// op's own `scope` takes and is the one an agent already has in its
969	    /// hand.
970	    private func nestScopePath(_ a: [String: Any], _ document: ProjectDocument) throws
971	        -> [NestScopeStep]
972	    {
973	        let snapshot = document.project.snapshot
974	        let wantsNest = a["nest"] != nil && !(a["nest"] is NSNull)
975	        let wantsClip = a["clip"] != nil && !(a["clip"] is NSNull)
976	        guard !(wantsNest && wantsClip) else {
977	            throw ToolError(
978	                message: "Pass nest or clip, not both — they are two spellings of one "
979	                    + "destination, and clip is the precise one.")
980	        }
981	        if wantsClip {
982	            let id = try idArg(a, "clip")
983	            guard let path = Self.pathToClip(id, in: snapshot) else {
984	                throw ToolError(
985	                    message: "No clip has id \(id), in this timeline or in any of its nests. "
986	                        + "get_project lists the clips, and each nest's own under nests.")
987	            }
988	            guard let clip = NestScope.clips(in: path, of: snapshot)
989	                .first(where: { $0.id == id }), let nest = clip.source.nestID
990	            else {
991	                throw ToolError(
992	                    message: "Clip \(id) does not show a nest, so there is nothing to open "
993	                        + "inside it. A nest clip's source.kind is \"nest\".")
994	            }
995	            return path + [NestScopeStep(nest: nest, clip: id)]
996	        }
997	        if wantsNest {
998	            let id = try idArg(a, "nest")
999	            guard snapshot.nest(id) != nil else {
1000	                throw ToolError(
1001	                    message: "no nest with id \(id). get_project lists them under nests.")
1002	            }
1003	            // The earliest TIMELINE clip that shows it, ties to the lower id.
1004	            // A nest shown only from INSIDE another nest is refused rather
1005	            // than guessed at: this is the view, and the app's way in is a
1006	            // clip you can point at. `clip` reaches it, and so does an op's
1007	            // own scope, which needs no view at all.
1008	            guard let entry = snapshot.clips
1009	                .filter({ $0.source.nestID == id })
1010	                .min(by: { ($0.start, $0.id) < ($1.start, $1.id) })
1011	            else {
1012	                throw ToolError(
1013	                    message: "No clip on the timeline shows nest \(id), so the view cannot "
1014	                        + "reach it in one step. Name the nest CLIP instead — set_scope "
1015	                        + "{clip: <id>} works at any depth — or send the op itself with "
1016	                        + "scope: \(id), which needs no view.")
1017	            }
1018	            return [NestScopeStep(nest: id, clip: entry.id)]
1019	        }
1020	        return []
1021	    }
1022	
1023	    /// The path from the timeline down to whichever container holds `clip`,
1024	    /// or nil when no container does.
1025	    ///
1026	    /// A breadth-first walk over the containers, with the nests it has
1027	    /// entered remembered: `check_nesting` refuses a cycle, so the visited
1028	    /// set is belt and braces against a hand-written file rather than against
1029	    /// anything the ops can make — but a walk that can be handed a project
1030	    /// from disk does not get to assume the file is sane.
1031	    private static func pathToClip(_ clip: UInt32, in snapshot: ProjectSnapshot)
1032	        -> [NestScopeStep]?
1033	    {
1034	        var queue: [[NestScopeStep]] = [[]]
1035	        var seen: Set<UInt32> = []
1036	        while !queue.isEmpty {
1037	            let path = queue.removeFirst()
1038	            let clips = NestScope.clips(in: path, of: snapshot)
1039	            if clips.contains(where: { $0.id == clip }) { return path }
1040	            for candidate in clips {
1041	                guard let nest = candidate.source.nestID, seen.insert(nest).inserted else {
1042	                    continue
1043	                }
1044	                queue.append(path + [NestScopeStep(nest: nest, clip: candidate.id)])
1045	            }
1046	        }
1047	        return nil
1048	    }
1049	
1050	    /// Moves the document to `path`, through the editor's own gestures where
1051	    /// there is an editor.
1052	    ///
1053	    /// **The gestures are reused rather than re-derived**, which matters
1054	    /// because entering maps the playhead (`t − nest_clip.start`) and leaving
1055	    /// maps it back and re-selects the clip: leave to the common prefix, then
1056	    /// enter one step at a time, and an agent's scope change is the same
1057	    /// event as a person's double-click — the player seeked, the timeline
1058	    /// scrolled, the breadcrumb redrawn.
1059	    ///
1060	    /// A windowless document (which an agent can make) has no gestures, so it
1061	    /// gets `setNestPath` directly with the playhead mapped through
1062	    /// `NestScope.offset` — the same sum `enterNest` arrives at one clip
1063	    /// start at a time, which is why the two cannot disagree.
1064	    private func applyNestScope(_ path: [NestScopeStep], _ document: ProjectDocument) {
1065	        guard path != document.nestPath else { return }
1066	        let snapshot = document.project.snapshot
1067	        guard let editor = editor(document) else {
1068	            let project = document.playhead + NestScope.offset(of: document.nestPath, in: snapshot)
1069	            let inside = max(0, project - NestScope.offset(of: path, in: snapshot))
1070	            // Coming OUT re-selects the nest clip that was entered, the way
1071	            // `leaveNest` does; going in selects nothing, the way `enterNest`
1072	            // does. "Coming out" is the case where the new path is a proper
1073	            // prefix of the old one.
1074	            let shared = Self.commonPrefix(document.nestPath, path)
1075	            let selection: Set<UInt32> =
1076	                path.count == shared && document.nestPath.count > shared
1077	                ? [document.nestPath[shared].clip] : []
1078	            document.setNestPath(path, playhead: inside, selection: selection)
1079	            return
1080	        }
1081	        editor.leaveAllNests(to: Self.commonPrefix(document.nestPath, path))
1082	        for step in path.dropFirst(document.nestPath.count) {
1083	            guard let clip = NestScope.clips(in: document.nestPath, of: snapshot)
1084	                .first(where: { $0.id == step.clip })
1085	            else { break }
1086	            editor.enterNest(clip)
1087	        }
1088	    }
1089	
1090	    /// How many leading steps two paths share.
1091	    private static func commonPrefix(_ a: [NestScopeStep], _ b: [NestScopeStep]) -> Int {
1092	        var shared = 0
1093	        while shared < a.count, shared < b.count, a[shared] == b[shared] { shared += 1 }
1094	        return shared
1095	    }
1096	
1097	    /// The scope as `get_project` and `set_scope` both report it.
1098	    ///
1099	    /// `scope` is the NEST id and nothing else, because it is the number an
1100	    /// op's own `scope` argument takes: a caller copies it straight across.
1101	    /// The clip it was entered through and the whole trail ride beside it
1102	    /// under their own names, and the whole group is `{"scope": null}` at the
1103	    /// timeline rather than absent, so "not in a nest" is an answer rather
1104	    /// than a missing key.
1105	    func scopeReport(_ document: ProjectDocument) -> [String: Any] {
1106	        guard let step = document.nestPath.last else { return ["scope": NSNull()] }
1107	        let snapshot = document.project.snapshot
1108	        let names = NestScope.names(of: document.nestPath, in: snapshot)
1109	        let trail = document.nestPath.enumerated().map { index, step -> [String: Any] in
1110	            // `names` opens with "Timeline", so a step's own name is one
1111	            // further along than its index.
1112	            ["nest": Int(step.nest), "clip": Int(step.clip), "name": names[index + 1]]
1113	        }
1114	        return [
1115	            "scope": Int(step.nest),
1116	            "scope_clip": Int(step.clip),
1117	            "scope_path": trail,
1118	        ]
1119	    }
1120	}
