1122	/// The container a call's id arguments are looked up in — the timeline, or
1123	/// the nest the envelope's `scope` named.
1124	///
1125	/// It is a value rather than a `ProjectSnapshot` of the view because an id
1126	/// lookup wants two lists and nothing else: assembling a whole view snapshot
1127	/// per reader would mean a second Swift spelling of `scoped_view`'s table
1128	/// (the canvas, the media, the emptied nest row) whose only reader compares
1129	/// integers. `core/src/scope.rs` owns that table, and it owns it alone.
1130	struct AgentIdScope {
1131	    /// nil on the timeline.
1132	    let nest: NestSnapshot?
1133	    let clips: [ClipSnapshot]
1134	    let tracks: [TrackSnapshot]
1135	    /// Whether the nest came from the call's own `scope` or from the nest the
1136	    /// app has open. It changes nothing about the lookup and one thing about
1137	    /// the message: how to get back to the timeline is a different sentence
1138	    /// for each.
1139	    let fromArgument: Bool
1140	
1141	    func clip(_ id: UInt32) -> ClipSnapshot? { clips.first { $0.id == id } }
1142	    func track(_ id: UInt32) -> TrackSnapshot? { tracks.first { $0.id == id } }
1143	
1144	    /// One track's clips in timeline order — `ProjectSnapshot.clips(onTrack:)`
1145	    /// asked of this container instead of the document, which is what
1146	    /// `remove_track`'s "still holds N clips" has to count inside a nest.
1147	    func clips(onTrack id: UInt32) -> [ClipSnapshot] {
1148	        clips.filter { $0.track == id }.sorted { $0.start < $1.start }
1149	    }
1150	
1151	    /// "No clip has id 17. get_project lists the clips." — and inside a
1152	    /// scope, the same sentence saying WHERE it looked.
1153	    ///
1154	    /// The unscoped spelling is byte for byte the one every one of these
1155	    /// readers has answered since M2, deliberately: it is what the tools'
1156	    /// own descriptions promise and what several proof scripts match on.
1157	    ///
1158	    /// The scoped one ends by saying how to get OUT, which is a different
1159	    /// sentence depending on how the call got in — dropping an argument does
1160	    /// nothing about a nest the window has open, and closing the nest does
1161	    /// nothing about an argument.
1162	    func noSuchId(_ kind: String, _ id: UInt32) -> String {
1163	        guard let nest = nest else {
1164	            return "No \(kind) has id \(id). get_project lists the \(kind)s."
1165	        }
1166	        let out =
1167	            fromArgument
1168	            ? "drop the scope to name one on the timeline"
1169	            : "that nest is OPEN in the view, so ids mean its own — set_scope with no "
1170	                + "arguments comes back out"
1171	        return "No \(kind) has id \(id) inside nest \(nest.id). get_project lists that nest's "
1172	            + "\(kind)s under nests; \(out)."
1173	    }
1174	}
