360	    /// `set_range` — Mark ▸ Set In / Set Out / Clear Range (I, O, ⌥X:
361	    /// `EditorViewController.setInPoint` / `setOutPoint` /
362	    /// `clearInOutRange`). View state like the playhead, so no op runs and
363	    /// nothing is undoable — but `export {range: "in_out"}` reads it, and
364	    /// `get_project` already reported it, so this is the write half of a
365	    /// field the agent could previously only look at.
366	    ///
367	    /// With neither bound the range is CLEARED, which is what ⌥X does.
368	    func setRange(_ a: [String: Any]) throws -> String {
369	        let document = try target(a)
370	        let start = try optionalTimeArg(a, "start", document)
371	        let end = try optionalTimeArg(a, "end", document)
372	        if start == nil && end == nil {
373	            document.inOutRange = nil
374	        } else {
375	            let from = max(0, start ?? document.inOutRange?.start ?? 0)
376	            let to = max(0, end ?? document.inOutRange?.end ?? document.project.duration)
377	            guard to > from else {
378	                throw ToolError(
379	                    message: "The range end (\(to)) must be after its start (\(from)); "
380	                        + "call set_range with no arguments to clear it.")
381	            }
382	            document.inOutRange = (start: from, end: to)
383	        }
384	        if let editor = editor(document) {
385	            editor.viewStateDidChange()
386	            editor.applyLoopRange()
387	        }
388	        var result: [String: Any] = ["ok": true, "project": summary(document)]
389	        if let range = document.inOutRange {
390	            result["in_out_range"] = ["start": range.start, "end": range.end]
391	        } else {
392	            result["in_out_range"] = NSNull()
393	        }
394	        return try jsonResult(result)
395	    }
