1050	    /// Moves the document to `path`, through the editor's own gestures where
1051	    /// there is an editor.
1052	    ///
1053	    /// **The gestures are reused rather than re-derived**, which matters
1054	    /// because entering maps the playhead (`t − nest_clip.start`) and leaving
1055	    /// maps it back and re-selects the clip: leave to the common prefix, then
1056	    /// enter one step at a time, and an agent's scope change is the same
1057	    /// event as a person's double-click — the player seeked, the timeline
1058	    /// scrolled, the breadcrumb redrawn.
1059	    ///
1060	    /// A windowless document (which an agent can make) has no gestures, so it
1061	    /// gets `setNestPath` directly with the playhead mapped through
1062	    /// `NestScope.offset` — the same sum `enterNest` arrives at one clip
1063	    /// start at a time, which is why the two cannot disagree.
1064	    private func applyNestScope(_ path: [NestScopeStep], _ document: ProjectDocument) {
1065	        guard path != document.nestPath else { return }
1066	        let snapshot = document.project.snapshot
1067	        guard let editor = editor(document) else {
1068	            let project = document.playhead + NestScope.offset(of: document.nestPath, in: snapshot)
1069	            let inside = max(0, project - NestScope.offset(of: path, in: snapshot))
1070	            // Coming OUT re-selects the nest clip that was entered, the way
1071	            // `leaveNest` does; going in selects nothing, the way `enterNest`
1072	            // does. "Coming out" is the case where the new path is a proper
1073	            // prefix of the old one.
1074	            let shared = Self.commonPrefix(document.nestPath, path)
1075	            let selection: Set<UInt32> =
1076	                path.count == shared && document.nestPath.count > shared
1077	                ? [document.nestPath[shared].clip] : []
1078	            document.setNestPath(path, playhead: inside, selection: selection)
1079	            return
1080	        }
1081	        editor.leaveAllNests(to: Self.commonPrefix(document.nestPath, path))
1082	        for step in path.dropFirst(document.nestPath.count) {
1083	            guard let clip = NestScope.clips(in: document.nestPath, of: snapshot)
1084	                .first(where: { $0.id == step.clip })
1085	            else { break }
1086	            editor.enterNest(clip)
1087	        }
1088	    }
