    /// thing an `offMainTools` handler may use to touch a document, AppKit or
    /// `RecipeSource`'s publish side.
    func onMain<T>(_ body: () throws -> T) rethrows -> T {
        try AgentLane.shared.onMainWhenIdle(body)
