100	    /// Places the whole of `media` as one clip at `at` on `track`, source
101	    /// in 0, with Fit scale when the canvas asks for it and the source
102	    /// exceeds it (spec §6).
103	    ///
104	    /// `video` is `null` for an audio-only file and `audio` is `null` for a
105	    /// file with no audio track, which is how the inspector knows which
106	    /// tabs to enable. Refuses when the placement breaks the overlap rule;
107	    /// `Err` for an unknown track or media, or a media with no usable
108	    /// duration.
109	    pub fn add_clip(&self, track: u32, media: u32, at: Ticks) -> Result<Outcome, String> {
110	        self.require_track(track)?;
111	        let found = self.require_media(media)?.clone();
112	        // A drag can start left of zero; the timeline has no negative time.
113	        let at = self.snapped(at).max(0);
114	
115	        let duration = self.whole_media_length(&found)?;
116	        let source = match found.kind {
117	            MediaKind::Image => Source::Image { media },
118	            MediaKind::Video | MediaKind::Audio => Source::Media {
119	                media,
120	                r#in: 0,
121	                reversed: false,
122	            },
123	            MediaKind::Lut => return Err(crate::lut::lut_not_placeable(media)),
124	        };
125	
126	        let has_pixels = found.has_video || matches!(found.kind, MediaKind::Image);
127	        let video = has_pixels.then(|| VideoProps {
128	            scale: self.fit_scale(f64::from(found.width), f64::from(found.height)),
129	            ..VideoProps::default()
130	        });
131	        let audio = found.has_audio.then(AudioProps::default);
132	
133	        let mut next = self.clone();
134	        let clip = Clip {
135	            video,
136	            audio,
137	            ..Clip::placed(next.allocate_id(), track, at, duration, source)
138	        };
139	        self.commit_additions(next, vec![clip])
