146	    ///
147	    /// The EARLIEST clip clamps at 0 and the rest keep their offsets, so a
148	    /// drag past the start of the timeline compresses nothing. The
149	    /// destination is computed as an index delta from the first clip of the
150	    /// selection (by track order, then start), which is what makes a
151	    /// two-track selection land two tracks apart.
152	    ///
153	    /// Refuses when a clip would land outside the track list or the overlap
154	    /// rule fails on any affected track. A clip that gains a predecessor
155	    /// overlap and has no transition gets a cross dissolve.
156	    ///
157	    /// **A linked partner follows in TIME, not in track** (spec §11 AU-91):
158	    /// every clip of the closure moves by the one delta, the clamp at 0 is
159	    /// taken over the closure so a J-cut's lead is kept, and the track delta
160	    /// is anchored on and applied to the CALLER's clips only — so a sound
161	    /// half dragged to a track of its own goes alone and its picture stays.
162	    pub fn move_clips(
163	        &self,
164	        clips: &[u32],
165	        delta: Ticks,
166	        track: Option<u32>,
167	    ) -> Result<Outcome, String> {
168	        let selection = self.selected_clips(clips)?;
169	        if selection.is_empty() {
170	            return Ok(Outcome::Identity);
171	        }
172	        let closure = self.selected_clips(&self.with_links(clips)?)?;
173	
174	        // Snapping the delta keeps a dragged clip on the grid: every start
175	        // is already on it, so a snapped delta lands on it too.
176	        let mut delta = self.snapped(delta);
177	        let earliest = closure.iter().map(|c| c.start).min().unwrap_or(0);
178	        if delta < -earliest {
179	            delta = -earliest;
180	        }
181	
182	        let index_delta = match track {
183	            None => 0i64,
184	            Some(destination) => {
185	                let destination_index = self.require_track_index(destination)? as i64;
186	                // The anchor is the FIRST clip of the selection in the
187	                // order the timeline draws — back-most track, then earliest
188	                // — and the whole selection moves by its offset, which is
189	                // what keeps a two-track selection two tracks apart.
190	                let mut keyed: Vec<(usize, Ticks, u32)> = Vec::new();
191	                for clip in &selection {
192	                    keyed.push((self.require_track_index(clip.track)?, clip.start, clip.id));
193	                }
194	                let anchor = keyed.iter().min().map(|k| k.0).unwrap_or(0) as i64;
195	                destination_index - anchor
196	            }
197	        };
198	
199	        let mut candidates: Vec<Clip> = Vec::new();
200	        for clip in &closure {
201	            let mut moved = (*clip).clone();
202	            moved.start = moved.start.saturating_add(delta).max(0);
203	            let named = selection.iter().any(|c| c.id == clip.id);
204	            if index_delta != 0 && named {
205	                let from = self.require_track_index(clip.track)? as i64;
206	                let to = from.saturating_add(index_delta);
207	                // A selection dragged off either end of the track list is a
208	                // refusal and not a clamp — clamping would silently stack
209	                // two clips on one track — and it says so in `move_track`'s
210	                // own words for the same mistake.
211	                let Some(destination) = usize::try_from(to)
212	                    .ok()
213	                    .and_then(|index| self.tracks.get(index))
214	                else {
215	                    return Ok(Outcome::Refused(format!(
216	                        "clip {} would land on track index {to}, which is out of range (0..{})",
217	                        clip.id,
218	                        self.tracks.len()
219	                    )));
220	                };
221	                moved.track = destination.id;
222	            }
223	            candidates.push(moved);
224	        }
225	
226	        self.commit_replacements(candidates)
227	    }
