229	    /// The named clips, deduplicated, in the order given. `Err` on an
230	    /// unknown id — every multi-clip op names its clips explicitly, so a
231	    /// stale id is a caller bug, not a refusal.
232	//! Slip and roll — spec §6 rows `slip` and `roll`.
233	//!
234	//! What separates these two from `edit_clip.rs`'s trims is that neither
235	//! changes how long the CUT is. A **slip** changes what a clip shows
236	//! without moving it: the window stays where it is on the timeline and the
237	//! film slides under it. A **roll** moves the frame two clips meet on
238	//! without moving anything else: one grows by exactly what the other loses.
239	//! They are what a cutter reaches for once the rough assembly is down, when
240	//! every following clip is already where it belongs and nothing may shift.
241	//!
242	//! Both are therefore *conservative* ops, and both are written to refuse
243	//! rather than approximate. A slip that has run out of source at one end
244	//! stops, and a slip that could not move at all is an identity — the
245	//! alternative is a drag that silently becomes a different, shorter edit
246	//! than the gesture asked for. A roll needs a hard cut to move: with a gap,
247	//! or with an overlap (which IS a transition, whose length is
248	//! `set_transition_duration`'s job), there is nothing here to roll.
249	//!
250	//! The arithmetic is `source_window.rs`'s — the three measurements of a
251	//! source window, the conversion into source ticks and the two last legal
252	//! positions all live there, and this module only clamps against them, so a
253	//! slip and a trim can never disagree about where a media ends.
254	
255	use crate::edit_clip::clip_end;
256	use crate::model::{Clip, Project, Source};
257	use crate::model_words::rebase_words;
258	use crate::outcome::Outcome;
259	use crate::recipe_graphic::graphic_advanced;
260	use crate::source_window::{source_advanced_through, timeline_to_source};
261	use crate::time::Ticks;
262	
263	impl Project {
264	    /// Slides the source window under a fixed clip: what the clip shows
265	    /// changes, where it sits does not (spec §6).
266	    ///
267	    /// `delta` is TIMELINE ticks — the distance the gesture travelled — so
268	    /// the source moves by `delta × speed`, the same conversion
269	    /// `trim_start` makes when it advances `in`. A positive `delta` shows
270	    /// LATER material, which is the direction the drag reads: pulling the
271	    /// clip right pulls the film forward under the window.
272	    ///
273	    /// Clamped so the window stays inside the media — `in ≥ 0` at the head,
274	    /// `in + duration × speed ≤ media.duration` at the tail — and a slip
275	    /// the clamps reduce to nothing is an identity. On a RAMPED clip the
276	    /// delta is converted at the base rate and the tail clamp is
277	    /// `file − S(D)` (`last_in_point` reads S); the actions do not move
278	    /// (spec §11 SR-18 (d)).
279	    ///
280	    /// A `still` has one source TIME rather than a window, so it moves that
281	    /// instead, clamped inside the media the same way. Every other source
282	    /// has nothing to slip and is an `Err` under the non-media rule.
283	    ///
284	    /// **The source kind is decided FIRST**, before the delta is even
285	    /// measured. A text clip named for a slip is an invalid argument
286	    /// whatever the delta was, and letting a sub-frame delta short-circuit
287	    /// to an identity would answer "valid, changes nothing" to a call that
288	    /// was never valid — the one answer the non-media rule exists to stop
289	    /// the MCP agent being given.
290	    ///
291	    /// Nothing moves, so there is no overlap to check and no transition can
292	    /// be gained; the actions are clip-relative and stay exactly where they
293	    /// are.
294	    ///
295	    /// **A linked partner on an unlocked track slips with it**, by the
296	    /// smaller in magnitude of the two clamped amounts, so the sound stays
297	    /// on its picture (spec §11 AU-94).
298	    pub fn slip(&self, clip: u32, delta: Ticks) -> Result<Outcome, String> {
299	        let target = self.require_clip(clip)?.clone();
300	        let delta = self.snapped(delta);
301	        let Some(own) = self.slip_amount(&target, delta)? else {
302	            return Ok(Outcome::Identity);
303	        };
304	        let partner = self
305	            .partner(clip)
306	            .filter(|p| self.track(p.track).is_some_and(|t| !t.locked))
307	            .cloned();
308	        let mut amount = own;
309	        if let Some(partner) = &partner {
310	            let theirs = self.slip_amount(partner, delta)?.unwrap_or(0);
311	            if theirs.abs() < amount.abs() {
312	                amount = theirs;
313	            }
314	        }
315	        if amount == 0 {
316	            return Ok(Outcome::Identity);
317	        }
318	
319	        let mut next = self.clone();
320	        for id in std::iter::once(clip).chain(partner.map(|p| p.id)) {
321	            if let Some(slot) = next.clip_mut(id) {
322	                slot.source = match &slot.source {
323	                    Source::Media {
324	                        media,
325	                        r#in,
326	                        reversed,
327	                    } => Source::Media {
328	                        media: *media,
329	                        r#in: r#in.saturating_add(amount),
330	                        reversed: *reversed,
331	                    },
332	                    Source::Still { media, at } => Source::Still {
333	                        media: *media,
334	                        at: at.saturating_add(amount),
335	                    },
336	                    other => other.clone(),
337	                };
338	            }
339	        }
340	        self.finish(next)
341	    }
342	
343	    /// How far, in SOURCE ticks, a slip of `delta` timeline ticks moves
344	    /// `clip` once clamped inside its media; `None` when the move rounds to
345	    /// nothing before the clamp. `Err` for a source with nothing to slip,
346	    /// decided FIRST (the doc above).
347	    fn slip_amount(&self, clip: &Clip, delta: Ticks) -> Result<Option<Ticks>, String> {
348	        let (media, current) = match clip.source {
349	            Source::Media { media, r#in, .. } => (media, r#in),
350	            Source::Still { media, at } => (media, at),
351	            _ => return Err(format!("clip {} is not a media clip", clip.id)),
352	        };
353	        // Timeline ticks to source ticks, at this clip's rate. A sub-tick
354	        // move at a very slow speed rounds to nothing, which is a refusal
355	        // and not an edit.
356	        let moved_by = timeline_to_source(delta, clip.speed);
357	        if moved_by == 0 {
358	            return Ok(None);
359	        }
360	
361	        // The last legal position of what the clip shows: a window is
362	        // pushed against the tail of the file, a still stops one frame
363	        // short of it. Both are `source_window.rs`'s, which is also where
364	        // the reasons for the two shapes are written down.
365	        let media = self.require_media(media)?;
366	        let last = match clip.source {
367	            Source::Still { .. } => self.last_still_time(media),
368	            _ => self.last_in_point(clip, media),
369	        };
370	        let slipped = current.saturating_add(moved_by).clamp(0, last);
371	        Ok(Some(slipped.saturating_sub(current)))
372	    }
373	
374	    /// Moves a hard cut: this clip's start and its predecessor's end both
375	    /// become `to`, and nothing else in the timeline moves (spec §6).
376	    ///
377	    /// The predecessor is the clip on the same track that ends EXACTLY at
378	    /// this clip's start. With no such clip the op refuses, naming the
379	    /// track and the start (spec §11 #88) — a gap has no cut to roll, and an
380	    /// overlap is a transition whose length `set_transition_duration` owns.
381	    ///
382	    /// `to` is clamped four ways, one pair per side: each clip keeps at
383	    /// least one frame, this clip may only reach back as far as its own
384	    /// source head allows (it grows at the FRONT, with front-trim
385	    /// semantics, so `in` follows), and the predecessor may only reach
386	    /// forward as far as its remaining source allows (it grows at the END,
387	    /// a plain end trim, so its `in` does not move). A `to` the clamps
388	    /// leave equal to the current cut is an identity, and so is a pair of
389	    /// clamps that cross — a cut with no legal position is not one this op
390	    /// can move.
391	    ///
392	    /// On a RAMPED clip this clip's `in` advances through its map, and the
393	    /// cut is held where it still fits its media (`front_edge_held`); the
394	    /// predecessor's bound reads its map on past its end (spec §11 SR-18
395	    /// (a), (c)).
396	    ///
397	    /// Neither clip's outer edge moves, so the pair still abuts exactly and
398	    /// no transition can be gained; the actions on both are clip-relative
399	    /// and stay where they are, as they do for a trim. This clip's
400	    /// `text.words` are rebased by the move, as `trim_start` rebases them
401	    /// (spec §11, W-3): a word stays on the speech it times. Its
402	    /// `graphic.in` advances by the move as `trim_start`'s does, and the
403	    /// predecessor's `length` is untouched (road map 10's G-9).
404	    ///
405	    /// Without `alone`, a linked partner whose start is this clip's and
406	    /// which has a hard-cut predecessor of its own is rolled to the same
407	    /// `to` after it (spec §11 AU-93, `carried_edge`); with it, the clip's
408	    /// cut moves alone.
409	    pub fn roll(&self, clip: u32, to: Ticks, alone: bool) -> Result<Outcome, String> {
410	        let hard_cut = |partner: &Clip| {
411	            self.clips_on_track(partner.track)
412	                .iter()
413	                .any(|c| c.id != partner.id && clip_end(c) == partner.start)
414	        };
415	        self.carried_edge(
416	            clip,
417	            alone,
418	            |target, partner| partner.start == target.start && hard_cut(partner),
419	            |project, id| project.roll_one(id, to),
420	        )
421	    }
422	
423	    fn roll_one(&self, clip: u32, to: Ticks) -> Result<Outcome, String> {
424	        let target = self.require_clip(clip)?.clone();
425	        let Some(previous) = self
426	            .clips_on_track(target.track)
427	            .into_iter()
428	            .find(|c| c.id != target.id && clip_end(c) == target.start)
429	            .cloned()
430	        else {
431	            return Ok(Outcome::Refused(format!(
432	                "no clip on track {} ends where clip {clip} begins ({}), so there is no cut \
433	                 to roll",
434	                target.track, target.start
435	            )));
436	        };
437	
438	        let frame = self.frame();
439	        let mut earliest = previous.start.saturating_add(frame);
440	        let mut latest = clip_end(&target).saturating_sub(frame);
441	        if let Some(start) = self.earliest_start_on_grid(&target) {
442	            earliest = earliest.max(start.max(0));
443	        }
444	        if let Some(end) = self.latest_end_on_grid(&previous) {
445	            latest = latest.min(end);
446	        }
447	        // The two source bounds arrive on the grid (`source_window.rs`
448	        // snaps each inward, and this pair is where that rule came from),
449	        // but the one-frame bounds are measured from the clips' own starts,
450	        // which a hand-written document may put off it. So both are snapped
451	        // INWARD again — up at the bottom, down at the top — and the cut
452	        // lands on a frame that is still inside the source both clips have.
453	        let earliest = self.snapped_up(earliest);
454	        let latest = self.snapped_down(latest);
455	        if earliest > latest {
456	            return Ok(Outcome::Identity);
457	        }
458	        let to = self.snapped(to).clamp(earliest, latest);
459	        // A ramped target's front edge is held where it still fits its
460	        // media, as `trim_start`'s is (spec §11 SR-18 (c)).
461	        let to = self.front_edge_held(&target, to);
462	        if to == target.start {
463	            return Ok(Outcome::Identity);
464	        }
465	
466	        let mut moved = target.clone();
467	        moved.source = source_advanced_through(&target, to.saturating_sub(target.start));
468	        moved.graphic = graphic_advanced(target.graphic.as_ref(), to.saturating_sub(target.start));
469	        moved.start = to;
470	        moved.duration = clip_end(&target).saturating_sub(to);
471	        if let Some(text) = moved.text.as_mut() {
472	            rebase_words(text, to.saturating_sub(target.start));
473	        }
474	
475	        let mut grown = previous.clone();
476	        grown.duration = to.saturating_sub(previous.start);
477	
478	        // The clamps make this unreachable for the pair itself; it is here
479	        // because every placement op checks, and because a track that
480	        // already held something the rule dislikes should not have it made
481	        // worse by an edit that thought it was safe.
482	        if let Err(why) =
483	            self.check_overlap_rule(&[moved.clone(), grown.clone()], target.track, &[])
484	        {
485	            return Ok(Outcome::Refused(why));
486	        }
487	
488	        let mut next = self.clone();
489	        if let Some(slot) = next.clip_mut(target.id) {
490	            *slot = moved;
491	        }
492	        if let Some(slot) = next.clip_mut(previous.id) {
493	            *slot = grown;
494	        }
495	        self.finish(next)
496	    }
497	}
498	//! Insert and overwrite — spec §6 rows `insert_clip` and `overwrite_clip`.
499	//!
500	//! The two ways to bring new material into a cut that is already timed.
501	//! An **insert** makes room for it: the track is cut under the drop point
502	//! and everything from there on moves later by the new clip's length, so
503	//! nothing is lost and every following clip keeps its relative timing. An
504	//! **overwrite** takes room from what is there: the span the new clip needs
505	//! is cleared on that track alone and nothing moves at all, so the cut's
506	//! total length and every other track are untouched — but for a cut clip's
507	//! linked partner, which `split_clips` cuts at the same bound (spec §11
508	//! AU-92).
509	//!
510	//! Both are compositions of ops that already exist — `split_clips`,
511	//! `insert_time`, `add_clip` — and both are ONE op anyway, for two reasons.
512	//! The first is undo: a drop from the media list is one gesture and must be
513	//! one step, and three ops applied in a row are three. The second is that
514	//! the composition has a rule in it that neither half states — an insert
515	//! cuts only the DESTINATION track and then shifts every unlocked one, so
516	//! the straddling clips elsewhere ride the shift whole (spec §11's rule 3)
517	//! while the one under the drop is cut. Written out at each call site, that
518	//! rule would be restated in the timeline, the menu and the MCP handler.
519	//!
520	//! Neither op invents a length: `whole_media_length` is what `add_clip`
521	//! itself uses, so the room an insert opens is exactly the room the clip
522	//! needs.
523	
524	use crate::edit_clip::clip_end;
525	use crate::edit_time::locked_track;
526	use crate::model::Project;
527	use crate::outcome::Outcome;
528	use crate::time::Ticks;
529	
530	impl Project {
531	    /// The insert edit: `media` lands whole at `at` on `track`, and
532	    /// everything at or after `at` moves later by its length (spec §6).
533	    ///
534	    /// The clip `at` falls strictly inside on THIS track is split first, so
535	    /// the insert lands between two clips rather than on top of one. Other
536	    /// tracks are not cut: `insert_time` shifts them whole, straddlers
537	    /// staying put, which is what keeps a music bed unbroken under an
538	    /// insert into the picture. The one exception is a cut clip's linked
539	    /// partner on an unlocked track, which `split_clips` cuts at the same
540	    /// `at` and pairs with it (spec §11 AU-92), so the pair stays in step
541	    /// through the inserted time.
542	    ///
543	    /// **A locked destination track refuses**, up front rather than by
544	    /// collision. `insert_time` will not shift a locked track, so the room
545	    /// an insert promises cannot be made there at all; leaving it to
546	    /// `add_clip` to notice would refuse only where the locked track
547	    /// happened to hold something at `at`, and quietly add a clip to a
548	    /// locked track everywhere else. `close_gap` refuses for the same
549	    /// reason.
550	    ///
551	    /// `Err` for an unknown track or media, or a media with no duration; a
552	    /// locked destination track refuses in [`locked_track`]'s words, and so
553	    /// does anything the inner `split`, `insert_time` or `add_clip` refused
554	    /// — this op answers in the words of whichever step declined.
555	    pub fn insert_clip(&self, track: u32, media: u32, at: Ticks) -> Result<Outcome, String> {
556	        if self.require_track(track)?.locked {
557	            return Ok(Outcome::Refused(locked_track(
558	                track,
559	                "an insert cannot open room on it",
560	            )));
561	        }
562	        let found = self.require_media(media)?.clone();
563	        let at = self.snapped(at).max(0);
564	        let length = self.whole_media_length(&found)?;
565	
566	        let straddling: Vec<u32> = self
567	            .clips_on_track(track)
568	            .iter()
569	            .filter(|c| c.start < at && at < clip_end(c))
570	            .map(|c| c.id)
571	            .collect();
572	        let mut next = match self.split_clips(&straddling, at)? {
573	            Outcome::Applied(split) => split,
574	            // Nothing straddled the insertion point, which is the ordinary
575	            // case: carry on with the project as it is.
576	            Outcome::Identity => self.clone(),
577	            Outcome::Refused(why) => return Ok(Outcome::Refused(why)),
578	        };
579	        match next.insert_time(at, length)? {
580	            Outcome::Applied(opened) => next = opened,
581	            Outcome::Identity => {}
582	            Outcome::Refused(why) => return Ok(Outcome::Refused(why)),
583	        }
584	        // A composition answers in the words of whichever step declined, so
585	        // the overlap rule's sentence reaches the caller through here too.
586	        let placed = match next.add_clip(track, media, at)? {
587	            Outcome::Applied(placed) => placed,
588	            Outcome::Identity => return Ok(Outcome::Identity),
589	            Outcome::Refused(why) => return Ok(Outcome::Refused(why)),
590	        };
591	        self.finish(placed)
592	    }
593	
594	    /// The overwrite edit: `media` lands whole at `at` on `track`, and
595	    /// whatever that track was playing across the span it needs is removed
596	    /// (spec §6). Nothing moves, and no other track is touched but for a
597	    /// cut clip's linked partner on an unlocked track: `split_clips` cuts it
598	    /// at the same bounds and pairs the pieces (spec §11 AU-92), and the
599	    /// partner's middle piece stays, its link settled away with the
600	    /// picture it was paired to.
601	    ///
602	    /// The span is cut at both bounds first, so everything that touched it
603	    /// afterwards lies entirely inside it and can be dropped whole; a clip
604	    /// that covered the whole span becomes a head and a tail with the new
605	    /// clip between them.
606	    ///
607	    /// The named track is cleared whether or not it is LOCKED — the caller
608	    /// named it, exactly as `ripple_delete` removes the clips it was given
609	    /// — while a lock still decides what may shift, which here is nothing.
610	    ///
611	    /// `Err` for an unknown track or media, or a media with no duration;
612	    /// whatever `add_clip` answered when the clip could not be placed after
613	    /// the span was cleared, in its own words.
614	    pub fn overwrite_clip(&self, track: u32, media: u32, at: Ticks) -> Result<Outcome, String> {
615	        self.require_track(track)?;
616	        let found = self.require_media(media)?.clone();
617	        let at = self.snapped(at).max(0);
618	        let length = self.whole_media_length(&found)?;
619	        // Both bounds are already on the frame grid, so the span is too.
620	        let end = at.saturating_add(length);
621	
622	        let mut next = self.clone();
623	        for bound in [at, end] {
624	            let cut: Vec<u32> = next
625	                .clips_on_track(track)
626	                .iter()
627	                .filter(|c| c.start < bound && bound < clip_end(c))
628	                .map(|c| c.id)
629	                .collect();
630	            match next.split_clips(&cut, bound)? {
631	                Outcome::Applied(project) => next = project,
632	                Outcome::Identity => {}
633	                Outcome::Refused(why) => return Ok(Outcome::Refused(why)),
634	            }
635	        }
636	        let inside: Vec<u32> = next
637	            .clips_on_track(track)
638	            .iter()
639	            .filter(|c| c.start >= at && clip_end(c) <= end)
640	            .map(|c| c.id)
641	            .collect();
642	        next.clips.retain(|c| !inside.contains(&c.id));
643	
644	        let placed = match next.add_clip(track, media, at)? {
645	            Outcome::Applied(placed) => placed,
646	            Outcome::Identity => return Ok(Outcome::Identity),
647	            Outcome::Refused(why) => return Ok(Outcome::Refused(why)),
648	        };
649	        self.finish(placed)
650	    }
651	}
652	//! Clip timing operations: trims and rate changes with source and action bounds.
653	
654	use crate::edit_clip::clip_end;
655	use crate::edit_speed_profile::profile_factors;
656	use crate::model::{Clip, Project, Source};
657	use crate::model_words::rebase_words;
658	use crate::outcome::Outcome;
659	use crate::recipe_graphic::graphic_advanced;
660	use crate::source_window::source_advanced_through;
661	use crate::time::Ticks;
662	
663	/// Speed range, `SPEED_MIN`–`SPEED_MAX` (spec §4.3, §11 #190). Three
664	/// readers: `set_speed` clamps to it, `rate_stretch` stays inside it, and
665	/// `Project::validate` refuses a clip outside it (spec §11 R6-10, amended by
666	/// #41). The app reads it through `rc_speed_limits` and never retypes it.
