723	    fn trim_start_one(&self, clip: u32, to: Ticks) -> Result<Outcome, String> {
724	        let target = self.require_clip(clip)?.clone();
725	        let end = clip_end(&target);
726	        let latest = end.saturating_sub(self.frame());
727	        let mut to = self.snapped(to).min(latest).max(0);
728	
729	        if let Some(earliest) = self.earliest_start_on_grid(&target) {
730	            to = to.max(earliest.max(0));
731	        }
732	        // A ramped clip's edge is held where the clip still fits its media
733	        // (spec §11 SR-18 (c)); a constant clip's is `to` as clamped.
734	        let to = self.front_edge_held(&target, to);
735	        // The two clamps can cross when the source has almost nothing left
736	        // in front: then there is no legal new start, so nothing happens.
737	        if to > latest || to == target.start {
738	            return Ok(Outcome::Identity);
739	        }
740	
741	        let delta = to.saturating_sub(target.start);
742	        let mut moved = target.clone();
743	        moved.source = source_advanced_through(&target, delta);
744	        moved.start = to;
745	        moved.duration = end.saturating_sub(to);
746	        moved.graphic = graphic_advanced(target.graphic.as_ref(), delta);
747	        if let Some(text) = moved.text.as_mut() {
748	            rebase_words(text, delta);
749	        }
750	        self.commit_replacements(vec![moved])
751	    }
