48	/// Default duration for a source with no source bound — text, shape, and an
49	/// image whose descriptor carries no duration. Five seconds is a common
50	/// title default and long enough to read.
51	pub(crate) const DEFAULT_CLIP_DURATION: Ticks = 5 * TIMESCALE;
52	
53	// ---- clip helpers --------------------------------------------------------
54	
55	pub(crate) fn clip_end(clip: &Clip) -> Ticks {
56	    /// (`source_window.rs`, spec §11): the nearest snap rounds UP past the
57	    /// end of the file, down-snapped `in + duration × speed ≤
58	    /// media.duration` holds and the rate is exactly 1. The price is a
59	    /// frame of the tail, and a media shorter than a frame, which is an
60	    /// `Err` naming the frame as one with no duration always has been.
61	    ///
62	    /// An image has no source bound and keeps the NEAREST snap of its
63	    /// descriptor's length or of the default — a constant is not on the
64	    /// grid of a rate that does not divide the timescale (at 30000/1001
65	    /// five seconds is 3 003 000 ticks, not 3 000 000), and the raw one
66	    /// made `insert_clip` open a hole wider than the clip it placed.
67	    pub(crate) fn whole_media_length(&self, media: &Media) -> Result<Ticks, String> {
68	        match media.kind {
69	            MediaKind::Lut => Err(crate::lut::lut_not_placeable(media.id)),
70	            MediaKind::Image if media.duration <= 0 => {
71	                Ok(self.snapped(DEFAULT_CLIP_DURATION).max(self.frame()))
72	            }
73	            MediaKind::Image => Ok(self.snapped(media.duration)),
74	            MediaKind::Video | MediaKind::Audio if media.duration <= 0 => Err(format!(
75	                "media {} has no duration ({} ticks)",
76	                media.id, media.duration
77	            )),
78	            MediaKind::Video | MediaKind::Audio => {
79	                // THE bound (`source_window.rs`) over the whole file from
80	                // tick 0 at 1:1; a literal 1.0 is always measurable.
81	                let duration = self
82	                    .longest_duration_on_grid_of(0, media, 0, 1.0)
83	                    .or_unbounded()
84	                    .unwrap_or(0);
85	                if duration <= 0 {
86	                    return Err(format!(
87	                        "media {} is shorter than a frame ({} ticks; a frame is {} ticks)",
88	                        media.id,
89	                        media.duration,
90	                        self.snapped_up(1)
91	                    ));
92	                }
93	                Ok(duration)
94	            }
95	        }
96	    }
